        raise ValueError("rows must be iterable") from exc
    result = []
    for row in iterator:
        if not isinstance(row, Mapping):
            raise ValueError("each row must be a mapping")
        output = {}
        for name in names:
            if name not in row:
                raise KeyError(name)
            output[name] = row[name]
        result.append(output)
    return result

