import unittest

from solution import extract_table


class OnceIterable:
    def __init__(self, values):
        self.values = values
        self.calls = 0

    def __iter__(self):
        self.calls += 1
        if self.calls > 1:
            raise AssertionError("iterable consumed more than once")
        return iter(self.values)


class ExtractTableTests(unittest.TestCase):
    def test_selection_order_row_order_and_exact_keys(self):
        rows = [
            {"a": 1, "b": 2, "ignored": 3},
            {"a": 4, "b": 5, "ignored": 6},
        ]
        result = extract_table(rows, (name for name in ["b", "a"]))
        self.assertEqual(result, [{"b": 2, "a": 1}, {"b": 5, "a": 4}])
        self.assertEqual([list(row) for row in result], [["b", "a"], ["b", "a"]])

    def test_empty_rows(self):
        self.assertEqual(extract_table([], ["a"]), [])

    def test_consumes_each_iterable_once(self):
        rows = OnceIterable([{"a": 1}])
        columns = OnceIterable(["a"])
        self.assertEqual(extract_table(rows, columns), [{"a": 1}])
        self.assertEqual(rows.calls, 1)
        self.assertEqual(columns.calls, 1)

    def test_column_validation(self):
        malformed = [[], "a", b"a", None, 1, [""], [1], ["a", "a"]]
        for columns in malformed:
            with self.subTest(columns=columns):
                with self.assertRaises(ValueError):
                    extract_table([], columns)

    def test_row_validation_and_missing_columns(self):
        for rows in ("rows", b"rows", None, 1, [1], [[("a", 1)]]):
            with self.subTest(rows=rows):
                with self.assertRaises(ValueError):
                    extract_table(rows, ["a"])
        with self.assertRaises(KeyError) as caught:
            extract_table([{"a": 1}], ["a", "b"])
        self.assertEqual(caught.exception.args, ("b",))

    def test_selected_values_are_deep_copied_from_input(self):
        source = {"nested": {"items": [1]}}
        result = extract_table([source], ["nested"])
        source["nested"]["items"].append(2)
        self.assertEqual(result, [{"nested": {"items": [1]}}])
        result[0]["nested"]["items"].append(3)
        self.assertEqual(source["nested"]["items"], [1, 2])

    def test_rows_and_calls_do_not_share_mutable_descendants(self):
        shared = {"items": [1]}
        first = extract_table([{"x": shared}, {"x": shared}], ["x"])
        second = extract_table([{"x": shared}], ["x"])
        first[0]["x"]["items"].append(2)
        self.assertEqual(first[1]["x"]["items"], [1])
        self.assertEqual(second[0]["x"]["items"], [1])
        self.assertEqual(shared["items"], [1])


if __name__ == "__main__":
    unittest.main()

